  COALESCE(value."ship_to_line2"."S"::varchar, value."ship_to_line2"."N"::varchar)::varchar(65535) AS ship_to_line2,
  COALESCE(value."ship_to_city"."S"::varchar, value."ship_to_city"."N"::varchar)::varchar(65535) AS ship_to_city,
  COALESCE(value."ship_to_state"."S"::varchar, value."ship_to_state"."N"::varchar)::varchar(65535) AS ship_to_state,
  COALESCE(value."ship_to_postal_code"."S"::varchar, value."ship_to_postal_code"."N"::varchar)::varchar(65535) AS ship_to_postal_code,
  COALESCE(value."ship_to_country"."S"::varchar, value."ship_to_country"."N"::varchar)::varchar(65535) AS ship_to_country,
  COALESCE(value."bill_to_line1"."S"::varchar, value."bill_to_line1"."N"::varchar)::varchar(65535) AS bill_to_line1,
  COALESCE(value."bill_to_line2"."S"::varchar, value."bill_to_line2"."N"::varchar)::varchar(65535) AS bill_to_line2,
  COALESCE(value."bill_to_city"."S"::varchar, value."bill_to_city"."N"::varchar)::varchar(65535) AS bill_to_city,
  COALESCE(value."bill_to_state"."S"::varchar, value."bill_to_state"."N"::varchar)::varchar(65535) AS bill_to_state,
  COALESCE(value."bill_to_postal_code"."S"::varchar, value."bill_to_postal_code"."N"::varchar)::varchar(65535) AS bill_to_postal_code,
  COALESCE(value."bill_to_country"."S"::varchar, value."bill_to_country"."N"::varchar)::varchar(65535) AS bill_to_country,
  COALESCE(value."card_type"."S"::varchar, value."card_type"."N"::varchar)::varchar(65535) AS card_type,
