  COALESCE(value."currency_to"."S"::varchar, value."currency_to"."N"::varchar)::varchar(65535) AS currency_to,
  CAST(NULLIF(COALESCE(value."currency_average_rate"."N"::varchar, value."currency_average_rate"."S"::varchar), '') AS decimal(19,4)) AS currency_average_rate
FROM aw_zetl_sales.public."aw-sales"
WHERE COALESCE(value."type"."S"::varchar, value."type"."N"::varchar)::varchar(64) = 'Order' AND COALESCE(value."deleted"."BOOL"::boolean, false) = false;

