WHERE COALESCE(value."type"."S"::varchar, value."type"."N"::varchar)::varchar(64) = 'SalesPerson' AND COALESCE(value."deleted"."BOOL"::boolean, false) = false;

-- aw-sales/SalesQuota  <- Sales.SalesPersonQuotaHistory
CREATE MATERIALIZED VIEW stg.sales_quota AUTO REFRESH YES AS
SELECT
  "PK"::varchar(2048) AS pk,
  "SK"::varchar(2048) AS sk,
  COALESCE(value."type"."S"::varchar, value."type"."N"::varchar)::varchar(64) AS type,
  COALESCE(value."src"."S"::varchar, value."src"."N"::varchar)::varchar(8) AS src,
  COALESCE(value."updated_at"."S"::varchar, value."updated_at"."N"::varchar)::varchar(32) AS updated_at,
  CAST(NULLIF(COALESCE(value."business_entity_id"."N"::varchar, value."business_entity_id"."S"::varchar), '') AS integer) AS business_entity_id,
  CAST(NULLIF(COALESCE(value."quota_date"."S"::varchar, value."quota_date"."N"::varchar), '') AS timestamp) AS quota_date,
  CAST(NULLIF(COALESCE(value."sales_quota"."N"::varchar, value."sales_quota"."S"::varchar), '') AS decimal(19,4)) AS sales_quota,
  COALESCE(value."rowguid"."S"::varchar, value."rowguid"."N"::varchar)::varchar(36) AS rowguid,
  CAST(NULLIF(COALESCE(value."modified_date"."S"::varchar, value."modified_date"."N"::varchar), '') AS timestamp) AS modified_date
FROM aw_zetl_sales.public."aw-sales"
WHERE COALESCE(value."type"."S"::varchar, value."type"."N"::varchar)::varchar(64) = 'SalesQuota' AND COALESCE(value."deleted"."BOOL"::boolean, false) = false;

